package com.bank.marketdata;

import java.util.concurrent.atomic.AtomicInteger;

// Simulates an off-heap native buffer. In reality this would wrap a
// ByteBuffer.allocateDirect or a JNI handle that MUST be freed.
class NativeBuffer {
    static final AtomicInteger openCount = new AtomicInteger(0);
    private final long handle;
    private volatile boolean freed = false;

    NativeBuffer(long handle) {
        this.handle = handle;
        openCount.incrementAndGet(); // pretend we reserved native memory
    }

    void free() {
        if (!freed) {
            freed = true;
            openCount.decrementAndGet(); // pretend we released native memory
        }
    }

    long handle() { return handle; }
}
