package com.bank.marketdata;

import java.lang.ref.Cleaner;
import java.util.logging.Logger;

// Holds a native buffer. Deterministic release via AutoCloseable;
// safety-net release via Cleaner. NEVER uses finalize().
class PriceFeedSubscription implements AutoCloseable {
    private static final Logger log = Logger.getLogger(PriceFeedSubscription.class.getName());

    // ONE shared cleaner for the whole class (daemon thread inside).
    private static final Cleaner CLEANER = Cleaner.create();

    private final NativeBuffer buffer;
    private final Cleaner.Cleanable cleanable;

    PriceFeedSubscription(String symbol, long handle) {
        this.buffer = new NativeBuffer(handle);
        // Register a cleanup action. CRITICAL: BufferState holds ONLY the
        // NativeBuffer, never 'this' — otherwise the object never dies.
        this.cleanable = CLEANER.register(this, new BufferState(buffer, symbol));
    }

    // Deterministic path: called by try-with-resources.
    @Override public void close() {
        cleanable.clean(); // runs the action now and de-registers it
    }

    long handle() { return buffer.handle(); }
}

// ─── Would be in BufferState.java in a real project ───
// The cleanup action. It is a top-level class holding ONLY resource state.
// It must NOT reference PriceFeedSubscription, or the Cleaner can never fire.
class BufferState implements Runnable {
    private static final Logger log = Logger.getLogger(BufferState.class.getName());
    private final NativeBuffer buffer;
    private final String symbol;

    BufferState(NativeBuffer buffer, String symbol) {
        this.buffer = buffer;
        this.symbol = symbol;
    }

    @Override public void run() {
        // Idempotent: safe whether called by close() or by the Cleaner thread.
        buffer.free();
        log.info(() -> "Freed native buffer for feed " + symbol
                + " (handle=" + buffer.handle() + ")");
    }
}
