package com.bank.marketdata;

import java.util.logging.*;

public class CleanerDemo {
    private static final Logger log = Logger.getLogger(CleanerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        log.info(() -> "Open native buffers at start: " + NativeBuffer.openCount.get());

        // PATH 1 — deterministic: try-with-resources frees immediately.
        try (PriceFeedSubscription sub = new PriceFeedSubscription("RELIANCE", 1001L)) {
            log.info(() -> "Using RELIANCE feed, handle=" + sub.handle()
                    + ", open buffers=" + NativeBuffer.openCount.get());
        } // close() called here -> buffer freed NOW
        log.info(() -> "After try-with-resources, open buffers: " + NativeBuffer.openCount.get());

        // PATH 2 — safety net: caller FORGETS to close.
        createAndForget();

        // Nudge the GC so the subscription becomes phantom-reachable and the
        // Cleaner thread runs the action. (Demo only; never rely on System.gc.)
        for (int i = 0; i < 5 && NativeBuffer.openCount.get() > 0; i++) {
            System.gc();
            Thread.sleep(200);
        }
        log.warning(() -> "After GC safety net, open buffers: " + NativeBuffer.openCount.get()
                + " (Cleaner released the forgotten buffer — no finalize, no resurrection)");
    }

    // Creates a subscription and lets it go out of scope WITHOUT closing.
    private static void createAndForget() {
        PriceFeedSubscription leaked = new PriceFeedSubscription("TCS", 2002L);
        log.warning(() -> "Created TCS feed but FORGOT to close it, handle=" + leaked.handle());
        // method returns; 'leaked' is now unreachable
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
